function installQualified(p=qualifiedPublished) {a.state.publicRows=a.validate(p);a.state.source=a.validateSource(p,a.state.publicRows);a.state.positionExclusions=Object.create(null);a.state.lastReadFailed=false;filters();a.updateView();return a.state.rows.find(r=>!r._local);}
await test('qualification accepts a later independent position check than the leaderboard read',()=>{const rows=a.validate(qualifiedPublished),source=a.validateSource(qualifiedPublished,rows);assert.equal(rows[0].positionCheck.count,3);assert.equal(rows[0].positionCheck.checkedAt,qualifiedPublished.traders[0].positionCheck.checkedAt);assert.equal(source.positionVerification.checkedAccounts,rows.length);assert.ok(Date.parse(rows[0].positionCheck.checkedAt)>Date.parse(rows[0].observedAt));});
for(const [name,mutate]of [
  ['unknown position scope',p=>p.traders[0].positionCheck.scope='all_markets'],
  ['zero verified positions',p=>p.traders[0].positionCheck.count=0],
  ['noninteger position count',p=>p.traders[0].positionCheck.count=1.2],
  ['position source older than 120 seconds',p=>p.traders[0].positionCheck.sourceTime=new Date(Date.parse(p.traders[0].positionCheck.checkedAt)-120001).toISOString()],
  ['position source more than five seconds ahead',p=>p.traders[0].positionCheck.sourceTime=new Date(Date.parse(p.traders[0].positionCheck.checkedAt)+5001).toISOString()],
  ['missing per-account check in qualified batch',p=>delete p.traders[0].positionCheck],
  ['inconsistent checked count',p=>p.source.positionVerification.checkedAccounts--],
  ['unaccounted candidate',p=>p.source.positionVerification.failedAccounts++],
  ['check after batch completion',p=>p.source.positionVerification.completedAt=new Date(Date.parse(p.traders[0].positionCheck.checkedAt)-1).toISOString()],
  ['extended qualification TTL',p=>p.source.positionVerification.maxAgeMinutes=120]
])await test('reject '+name,()=>{const p=structuredClone(qualifiedPublished);mutate(p);assert.throws(()=>a.validateSource(p,a.validate(p)),/校验/);});
